	CMouseDraggedEvent_AC() : CMouseEvent_AC() {}	CMouseDraggedEvent_AC(EventRef inEvent) : CMouseEvent_AC(inEvent) { AssertKind(kEventKind); }	CMouseDraggedEvent_AC(const CCarbonEvent_AC& inEvent) : CMouseEvent_AC(inEvent) { AssertKind(kEventKind); }	CMouseDraggedEvent_AC(const CMouseDraggedEvent_AC& inEvent) : CMouseEvent_AC(inEvent) {}	~CMouseDraggedEvent_AC() {}	// Parameters	CPoint_AC GetMouseLocation() const	{ return GetParameter<CPoint_AC>(kEventParamMouseLocation, typeQDPoint); }	UInt32 GetKeyModifiers() const	{ return GetParameter<UInt32>(kEventParamKeyModifiers, typeUInt32); }	EventMouseButton GetMouseButton() const	{ return GetParameter<EventMouseButton>(kEventParamMouseButton, typeMouseButton); }};//========================================================================================// CMouseWheelMovedEvent_AC//========================================================================================class CMouseWheelMovedEvent_AC : public CMouseEvent_AC{public:	enum { kEventKind = kEventMouseWheelMoved };	CMouseWheelMovedEvent_AC() : CMouseEvent_AC() {}	CMouseWheelMovedEvent_AC(EventRef inEvent) : CMouseEvent_AC(inEvent) { AssertKind(kEventKind); }	CMouseWheelMovedEvent_AC(const CCarbonEvent_AC& inEvent) : CMouseEvent_AC(inEvent) { AssertKind(kEventKind); }	CMouseWheelMovedEvent_AC(const CMouseWheelMovedEvent_AC& inEvent) : CMouseEvent_AC(inEvent) {}	~CMouseWheelMovedEvent_AC() {}	// Parameters	CPoint_AC GetMouseLocation() const	{ return GetParameter<CPoint_AC>(kEventParamMouseLocation, typeQDPoint); }	UInt32 GetKeyModifiers() const	{ return GetParameter<UInt32>(kEventParamKeyModifiers, typeUInt32); }	EventMouseWheelAxis GetMouseWheelAxis() const	{ return GetParameter<EventMouseWheelAxis>(kEventParamMouseWheelAxis, typeMouseWheelAxis); }	long GetMouseWheelDelta() const	{ return GetParameter<long>(kEventParamMouseWheelDelta, typeLongInteger); }};//===================================================================